import math
from dataclasses import dataclass, field
from enum import Enum
from typing import Union

class Kind(Enum):
    CIRCLE = "circle"
    SQUARE = "square"

@dataclass(frozen=True)
class Circle:
    radius: float
    kind: Kind = field(default=Kind.CIRCLE, init=False)

@dataclass(frozen=True)
class Square:
    side: float
    kind: Kind = field(default=Kind.SQUARE, init=False)

Shape = Union[Circle, Square]                # 3.7+: no X | Y syntax yet

def area(shape: Shape) -> float:
    if isinstance(shape, Circle):
        return math.pi * shape.radius ** 2
    if isinstance(shape, Square):
        return shape.side ** 2
    raise TypeError(shape)
